package android.os;import java.util.*;public class Messenger implements Parcelable {public boolean dead;private Handler handler;private List<IBinder.DeathRecipient> deaths=new ArrayList<>();private final IBinder binder=new IBinder(){public boolean isBinderAlive(){return !dead;}public void linkToDeath(IBinder.DeathRecipient r,int f)throws RemoteException{if(dead)throw new RemoteException();deaths.add(r);}public boolean unlinkToDeath(IBinder.DeathRecipient r,int f){return deaths.remove(r);}};public Messenger(Handler h){handler=h;}public IBinder getBinder(){return binder;}public void kill(){dead=true;for(IBinder.DeathRecipient r:new ArrayList<>(deaths))r.binderDied();}public void send(Message m)throws RemoteException{if(dead)throw new RemoteException();handler.post(()->handler.handleMessage(m));}}
